 showSetup(){document.getElementById('app').innerHTML=`<div class="modal"><div class="modalbox"><img src="icons/finmate-icon-192.png?v=3.3" class="logo"><h2>Welcome to FinMate</h2><p class="note">Create a private local vault. Your financial records are encrypted before storage.</p><div class="field"><label>Master password</label><input id="pw1" type="password" autocomplete="new-password"></div><div class="field"><label>Confirm password</label><input id="pw2" type="password"></div><button class="btn primary full" onclick="APP.setupGo()">Create local vault</button><p class="note">Keep this password safe. It is the root of your local encryption key.</p><footer class="preunlock-links"><a href="/privacy" target="_blank" rel="noopener">Privacy Policy</a><a href="/terms" target="_blank" rel="noopener">Terms of Service</a><a href="/help" target="_blank" rel="noopener">Help</a></footer><footer class="finmate-copyright">© ${new Date().getFullYear()} Sivakumar Subramani. All rights reserved. Independently developed and maintained.</footer></div></div>`},
