 showUnlockForm(mode){const box=document.getElementById('unlockForm');if(!box)return;if(mode==='pin'){box.innerHTML=`<div class="unlock-form"><div class="field"><label>4-digit PIN</label><input id="pinUnlockInput" inputmode="numeric" pattern="\d{4}" maxlength="4" type="password" autocomplete="one-time-code" placeholder="••••" oninput="this.value=this.value.replace(/\D/g,'').slice(0,4)" onkeydown="if(event.key==='Enter')APP.unlockPinGo()"></div><button class="btn primary full" onclick="APP.unlockPinGo()">Unlock with PIN</button></div>`}else if(mode==='bio'){box.innerHTML=`<div class="unlock-form"><p class="note">Opening your device fingerprint / biometric prompt…</p></div>`;setTimeout(()=>this.unlockBiometricGo(),0)}else{box.innerHTML=`<div class="unlock-form"><div class="field"><label>Master password</label><input id="pw" type="password" autocomplete="current-password" onkeydown="if(event.key==='Enter')APP.unlockGo()"></div><button class="btn primary full" onclick="APP.unlockGo()">Unlock with password</button></div>`}setTimeout(()=>box.querySelector('input,button')?.focus(),0)},
 async setupGo(){const a=document.getElementById('pw1').value,b=document.getElementById('pw2').value;if(a.length<8)return alert('Use at least 8 characters.');if(a!==b)return alert('Passwords do not match.');await this.createVault(a);const rec=await this.idbGet();if(rec)this.showUnlock(rec)},
