 async adoptPendingGoogleToken(){const rt=sessionStorage.getItem('finmate_google_refresh_token');if(this.state){if(rt){this.state.sync={...(this.state.sync||{}),refreshToken:rt,oauthBackend:this.state.sync?.oauthBackend||localStorage.getItem('finmate_oauth_backend')||''};sessionStorage.removeItem('finmate_google_refresh_token')}else if(!this.state.sync?.oauthBackend&&localStorage.getItem('finmate_oauth_backend')){this.state.sync={...(this.state.sync||{}),oauthBackend:localStorage.getItem('finmate_oauth_backend')||''}}/* Do not re-encrypt the entire vault during the OAuth return/unlock path. The explicit Drive operation persists settings once, after folder resolution. */if(this.pendingDriveAction==='pull'||this.pendingDriveAction==='push'||this.pendingDriveAction==='compare'||this.pendingDriveAction==='baseline-review'||this.pendingDriveAction==='three-way-review'){const action=this.pendingDriveAction;this.pendingDriveAction='';setTimeout(()=>action==='compare'?this.compareDriveChanges():action==='baseline-review'?this.reviewSharedBaseline():action==='three-way-review'?this.reviewThreeWayConflicts():this.driveSync(action),150)}return;}},
 async unlockGo(){await this.unlock(document.getElementById('pw').value,this.pendingRec)},
 async unlockPinGo(){try{if(!this.pendingRec?.pinWrap)return alert('This older vault has PIN enabled but its local PIN wrapper is missing. Unlock once with the master password to repair the PIN unlock record.');const pin=document.getElementById('pinUnlockInput')?.value;if(!/^\d{4}$/.test(pin||''))return alert('Enter your 4-digit PIN.');const raw=await this.unwrapKey(this.pendingRec.pinWrap,pin);this.cryptoKey=await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},true,['encrypt','decrypt']);this.state=await this.decrypt(this.pendingRec,this.cryptoKey);{const wasSuppressed=this.journalSuppressed;this.journalSuppressed=true;try{this.migrate();await this.persist(true);await this.autoGenerateDue()}finally{this.journalSuppressed=wasSuppressed}}await this.repairUnlockWrappers(this.pendingRec);await this.adoptPendingGoogleToken();await this.journalPendingCount();this.render()}catch(e){alert('Incorrect PIN.')}},
 async setupPin(){this.modal('Set 4-digit PIN',`<p class="note">Your PIN is used only to unwrap the local encryption key. It is never stored in plain text.</p><div class="field"><label>New 4-digit PIN</label><input id="pin1" type="password" inputmode="numeric" maxlength="4" autocomplete="new-password" placeholder="••••" oninput="this.value=this.value.replace(/\D/g,'').slice(0,4)"></div><div class="field"><label>Confirm 4-digit PIN</label><input id="pin2" type="password" inputmode="numeric" maxlength="4" autocomplete="new-password" placeholder="••••" oninput="this.value=this.value.replace(/\D/g,'').slice(0,4)"></div>`,async()=>{const a=document.getElementById('pin1').value,b=document.getElementById('pin2').value;if(!/^\d{4}$/.test(a))throw new Error('PIN must contain exactly 4 digits.');if(a!==b)throw new Error('PINs do not match.');const raw=await crypto.subtle.exportKey('raw',this.cryptoKey);this.state.security={...(this.state.security||{}),pinWrap:await this.wrapKey(raw,a)};await this.persist();const rec=await this.idbGet();if(rec){rec.pinWrap=this.state.security.pinWrap;rec.pinEnabled=true;await this.idbPut(rec)}alert('PIN unlock enabled. Lock FinMate and choose 4-digit PIN on the unlock screen.')})},
