 money(n,c=this.state.currency||'INR'){if(this.privacy)return '••••••';try{return new Intl.NumberFormat('en-IN',{style:'currency',currency:c,maximumFractionDigits:3,minimumFractionDigits:0}).format(Number(n)||0)}catch{return String(Number(n)||0)}},
