  const unique=new Map();for(const r of data){const name=String(r[ni]||'').trim();if(!name)continue;const key=name.toLowerCase();if(!unique.has(key))unique.set(key,{name,type:typei>=0?String(r[typei]||''):'' ,isin:isini>=0?String(r[isini]||''):'',ticker:ti>=0?String(r[ti]||'').trim():''})}
