  let m=s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);
  if(m){let a=Number(m[1]),b=Number(m[2]),y=Number(m[3]); if(y<100)y+=2000; let day=format==='mdy'?b:a,mon=format==='mdy'?a:b; if(day>=1&&day<=31&&mon>=1&&mon<=12)return `${y}-${String(mon).padStart(2,'0')}-${String(day).padStart(2,'0')}`;}
  m=s.match(/^(\d{4})[\/\-.](\d{1,2})[\/\-.](\d{1,2})$/); if(m)return `${m[1]}-${String(Number(m[2])).padStart(2,'0')}-${String(Number(m[3])).padStart(2,'0')}`;
