 async authorizeGoogle(){try{const token=await this.getDriveToken();this.driveToken=token;if(this.state?.sync?.refreshToken)sessionStorage.removeItem('finmate_google_refresh_token');if(this.state&&this.cryptoKey)await this.persist(true);this.render();alert('Google authorization is ready for this session. No upload or retrieval was started. Use Upload or Retrieve when you are ready.')}catch(e){if(e?.code==='secure_oauth_required'||String(e?.message||'').includes('Secure Google authorization is required.')){return this.secureGoogleConnect('connect')}console.error('FinMate Google authorization failed',e);alert(`Google authorization failed: ${e?.message||e}`)}},
