   const lines=details.slice(0,80).map(x=>`${x.status.toUpperCase()} · ${x.collection} · ${x.label} · ID ${x.id}`);
   const text=`FinMate detailed read-only comparison\n\nLocal pending journal entries: ${pending}\nLocal-only records: ${summary.localOnly}\nDrive-only records: ${summary.driveOnly}\nSame-ID records with different content: ${summary.different}\nSame-ID records with matching content: ${summary.same}\n\n${lines.length?lines.join('\n'):'No records with differences were found.'}${details.length>80?`\n\nShowing first 80 of ${details.length} differences in this preview.`:''}\n\nThis comparison is read-only. Nothing was uploaded, retrieved, merged, or changed. Local-only and Drive-only do not prove which version is newer.`;
