     try{const shared=await this.publishSharedBaseline(token,folderId,{...baseline,collections,localHashes:makeHashes(localProfile),driveHashes:makeHashes(remoteProfile)});alert(`Shared baseline saved and read-back verified. Records fingerprinted: ${Object.values(shared.recordCounts).reduce((a,b)=>a+b,0)}. It is encrypted and contains fingerprints only; no record contents were uploaded. No merge was performed.`)}catch(sharedError){console.error('FinMate shared baseline publish failed',sharedError);alert(`Shared baseline was not completed: ${sharedError.message||sharedError}. The existing vault and local records were not changed.`)}
